INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Kalkulation von Leistungen Teil der Leistungsrechnung?', 2, '[{"text": "Ja", "correct": true, "because": "Kernaufgabe der Leistungsrechnung"}, {"text": "Nein", "correct": false, "because": "Definition der Leistungsrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird bei der Kalkulation von Leistungen nur die Arbeitszeit berücksichtigt?', 2, '[{"text": "Ja", "correct": false, "because": "Auch Material und andere Kosten werden einbezogen"}, {"text": "Nein", "correct": true, "because": "Umfassende Kostenbetrachtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Kalkulation von Leistungen zur Preisbestimmung genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Dient der Grundlage für Preise"}, {"text": "Nein", "correct": false, "because": "Preisgestaltung ist ein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Kalkulation von Leistungen Gemeinkosten berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Vollständige Kostenkalkulation"}, {"text": "Nein", "correct": false, "because": "Gemeinkosten sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kalkulation von Leistungen nur für materielle Produkte relevant?', 2, '[{"text": "Ja", "correct": false, "because": "Auch Dienstleistungen werden kalkuliert"}, {"text": "Nein", "correct": true, "because": "Gilt für Produkte und Dienstleistungen"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Kalkulation von Leistungen?', 2, '[{"text": "Ermittlung der Kosten einer Leistung", "correct": true, "because": "Grundlage der Leistungsrechnung"}, {"text": "Festlegung der Arbeitszeiten", "correct": false, "because": "Nur ein Teilaspekt"}, {"text": "Berechnung der Gewinne", "correct": false, "because": "Folge, kein Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart wird bei der Kalkulation von Leistungen immer einbezogen?', 3, '[{"text": "Einzelkosten", "correct": true, "because": "Direkt zurechenbare Kosten"}, {"text": "Fixkosten", "correct": false, "because": "Nicht immer direkt"}, {"text": "Variable Kosten", "correct": false, "because": "Nur ein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird häufig für die Kalkulation von Leistungen verwendet?', 2, '[{"text": "Zuschlagskalkulation", "correct": true, "because": "Verteilt Gemeinkosten"}, {"text": "Bilanzierung", "correct": false, "because": "Anderes Verfahren"}, {"text": "Abschreibung", "correct": false, "because": "Kein Kalkulationsverfahren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn die Kalkulation von Leistungen ungenau ist?', 3, '[{"text": "Falsche Preisgestaltung", "correct": true, "because": "Kostenbasis fehlerhaft"}, {"text": "Höhere Fixkosten", "correct": false, "because": "Kein direkter Zusammenhang"}, {"text": "Weniger Arbeitszeit", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Basis wird oft für die Kalkulation von Leistungen herangezogen?', 2, '[{"text": "Kostenstellen", "correct": true, "because": "Kosten werden zugeordnet"}, {"text": "Umsatz", "correct": false, "because": "Folge, keine Basis"}, {"text": "Mitarbeiterzahl", "correct": false, "because": "Kein direkter Bezug"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten werden bei der Kalkulation von Leistungen berücksichtigt?', 4, '[{"text": "Einzelkosten", "correct": true, "because": "Direkt zurechenbar"}, {"text": "Gemeinkosten", "correct": true, "because": "Indirekte Kosten"}, {"text": "Abschreibungen", "correct": true, "because": "Teil der Gemeinkosten"}, {"text": "Privatkosten", "correct": false, "because": "Nicht betrieblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ziele verfolgt die Kalkulation von Leistungen?', 3, '[{"text": "Kostenermittlung", "correct": true, "because": "Hauptzweck"}, {"text": "Preisgestaltung", "correct": true, "because": "Grundlage für Preise"}, {"text": "Mitarbeiterplanung", "correct": false, "because": "Kein direkter Zweck"}, {"text": "Gewinnanalyse", "correct": true, "because": "Folge der Kalkulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Kalkulation von Leistungen?', 4, '[{"text": "Arbeitszeit", "correct": true, "because": "Direkter Kostenfaktor"}, {"text": "Materialverbrauch", "correct": true, "because": "Einzelkosten"}, {"text": "Wetterbedingungen", "correct": false, "because": "Kein direkter Einfluss"}, {"text": "Gemeinkostenzuschläge", "correct": true, "because": "Verteilung indirekter Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden können bei der Kalkulation von Leistungen angewendet werden?', 3, '[{"text": "Zuschlagskalkulation", "correct": true, "because": "Verteilt Gemeinkosten"}, {"text": "Divisionskalkulation", "correct": true, "because": "Für gleichartige Leistungen"}, {"text": "Bilanzierung", "correct": false, "because": "Kein Kalkulationsverfahren"}, {"text": "Äquivalenzziffernkalkulation", "correct": true, "because": "Für unterschiedliche Leistungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Kalkulation von Leistungen?', 3, '[{"text": "Transparenz über Kosten", "correct": true, "because": "Klarheit geschaffen"}, {"text": "Genauere Preisgestaltung", "correct": true, "because": "Kostenbasis"}, {"text": "Senkung der Fixkosten", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Wettbewerbsfähigkeit", "correct": true, "because": "Realistische Preise"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Kalkulation von Leistungen ermittelt die Kosten. b) Sie ist nur für Produkte relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (auch Dienstleistungen)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gemeinkosten werden in der Kalkulation einbezogen. b) Einzelkosten sind irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Einzelkosten wichtig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Kalkulation von Leistungen dient der Preisgestaltung. b) Sie ignoriert die Arbeitszeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Arbeitszeit relevant)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Zuschlagskalkulation ist eine Methode der Leistungskalkulation. b) Sie betrifft nur Fixkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (auch Gemeinkosten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ungenaue Kalkulation führt zu falschen Preisen. b) Sie verbessert die Kostenübersicht.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Preise betroffen, b) Übersicht verbessert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
